mapper.select:
SELECT PC.CATEGORY_ID AS categoryId, PC.CATEGORY_NAME AS categoryName, P.PRODUCT_ID AS productId, P.PRODUCT_NAME AS productName, R.REGION_ID AS regionId, R.REGION_NAME AS regionName, C.COUNTRY_ID AS countryId, C.COUNTRY_NAME AS countryName, L.LOCATION_ID AS locationId, L.ADDRESS AS locationName, W.WAREHOUSE_ID AS warehouseId, W.WAREHOUSE_NAME AS warehouseName, P.DESCRIPTION AS description FROM INVENTORIES I, PRODUCTS P, PRODUCT_CATEGORIES PC, WAREHOUSES W, LOCATIONS L, COUNTRIES C, REGIONS R
AND I.PRODUCT_ID = P.PRODUCT_ID AND P.CATEGORY_ID = PC.CATEGORY_ID AND I.WAREHOUSE_ID = W.WAREHOUSE_ID AND W.LOCATION_ID = L.LOCATION_ID AND L.COUNTRY_ID = C.COUNTRY_ID AND C.REGION_ID = R.REGION_ID
AND PC.CATEGORY_ID = #{categoryId}
AND ( UPPER(REPLACE(TRIM(P.PRODUCT_NAME), ' ', '')) LIKE '%' || UPPER(REPLACE(TRIM(#{productName}), ' ', '')) || '%' )
AND ( UPPER(REPLACE(TRIM(W.WAREHOUSE_NAME), ' ', '')) LIKE '%' || UPPER(REPLACE(TRIM(#{warehouseName}), ' ', '')) || '%' )
AND R.REGION_ID = #{regionId}
AND C.COUNTRY_ID = #{countryId}
AND L.LOCATION_ID = #{locationId}
ORDER BY P.PRODUCT_NAME, W.WAREHOUSE_NAME

mapper.update:
UPDATE INVENTORIES
SET QUANTITY = #{quantity}
WHERE PRODUCT_ID = #{productId}
  AND WAREHOUSE_ID = #{warehouseId}

mapper.select:
SELECT COUNT(*)
  FROM ORDER_ITEMS
WHERE PRODUCT_ID = #{productId}

mapper.update:
UPDATE INVENTORIES
SET QUANTITY = 0
WHERE PRODUCT_ID = #{productId}
  AND WAREHOUSE_ID = #{warehouseId}

mapper.select:
SELECT COUNT(*)
  FROM INVENTORIES
WHERE PRODUCT_ID = #{productId}
  AND WAREHOUSE_ID = #{warehouseId}

mapper.update:
UPDATE INVENTORIES
SET QUANTITY = NVL(QUANTITY, 0) + NVL(#{quantity}, 0)
WHERE PRODUCT_ID = #{productId}
  AND WAREHOUSE_ID = #{warehouseId}

mapper.insert:
